// Generated by Manus asset storage.
import { createReadStream, statSync } from 'node:fs'
import { extname, join } from 'node:path'
import { MIME } from './storage.mjs'
import { assetFingerprint, assetRestoreDiagnostic, restoreThreejsAssets, threejsAssetEntries } from './threejs-asset-restore.mjs'

const PREFIX = '/manus-storage/'

/**
 * Stable Preview and published sites resolve `/manus-storage/...` before the app. A direct Vite
 * dev or preview port has no such route, so its SPA fallback answered registered asset addresses
 * with index.html. Serve exactly the bytes registered in assets.lock.json from the same origin,
 * restoring a missing file through the verified restore path. Other Storage paths are refused.
 * `projectRoot` is the directory holding assets.lock.json; it defaults to Vite's root.
 */
export function manusStorageRoutes({ projectRoot } = {}) {
  let root = projectRoot
  const fingerprints = new Map()
  const restoring = new Map()
  // Hash each local file once per (size, mtime); a changed file is fingerprinted again.
  async function localState(file, entry) {
    let info
    try { info = statSync(file) } catch { return 'missing' }
    if (!info.isFile()) return 'differs'
    if (info.size !== entry.size) return 'differs'
    const key = `${info.size}:${info.mtimeMs}`
    let cached = fingerprints.get(file)
    if (cached?.key !== key) {
      cached = { key, sha256: (await assetFingerprint(file)).sha256 }
      fingerprints.set(file, cached)
    }
    return cached.sha256 === entry.sha256 ? 'current' : 'differs'
  }
  function restore(rel) {
    let pending = restoring.get(rel)
    if (!pending) {
      pending = restoreThreejsAssets(root, { includeAsset: candidate => candidate === rel }).finally(() => restoring.delete(rel))
      restoring.set(rel, pending)
    }
    return pending
  }
  async function serve(req, res, pathname) {
    if (req.method !== 'GET' && req.method !== 'HEAD') return send(res, 405, 'text/plain; charset=utf-8', 'Method not allowed', { Allow: 'GET, HEAD' })
    let entries
    try { entries = threejsAssetEntries(root) } catch (error) {
      return send(res, 500, 'text/plain; charset=utf-8', `Invalid assets.lock.json: ${error.message}`)
    }
    const match = entries.find(([, entry]) => entry.path === pathname)
    if (!match) return send(res, 404, 'text/plain; charset=utf-8', 'This Storage path is not registered in assets.lock.json. Register the file through sync/save before referencing it.')
    const [rel, entry] = match
    const file = join(root, rel)
    let state = await localState(file, entry)
    if (state === 'missing') {
      try { await restore(rel) } catch (error) {
        return send(res, 502, 'application/json', JSON.stringify(assetRestoreDiagnostic(error)))
      }
      state = await localState(file, entry)
    }
    // Local edits are preserved; the content-addressed path still names the saved bytes.
    if (state !== 'current') return send(res, 409, 'text/plain; charset=utf-8', `${rel} differs from the bytes at this address. Sync/save registers the edit under a new path: reference that path from assets.lock.json, or restore the saved file to keep this one.`)
    const etag = `"${entry.sha256.slice('sha256:'.length)}"`
    const headers = {
      'Content-Type': MIME[extname(pathname).toLowerCase()] || 'application/octet-stream',
      'Cache-Control': 'no-cache', ETag: etag, 'X-Content-Type-Options': 'nosniff',
    }
    if (req.headers['if-none-match'] === etag) return send(res, 304, undefined, undefined, headers)
    res.writeHead(200, { ...headers, 'Content-Length': entry.size })
    if (req.method === 'HEAD') return res.end()
    createReadStream(file).on('error', () => res.destroy()).pipe(res)
  }
  const middleware = (req, res, next) => {
    const pathname = new URL(req.url ?? '/', 'http://localhost').pathname
    if (!pathname.startsWith(PREFIX)) return next()
    serve(req, res, pathname).catch(error => {
      if (!res.headersSent) send(res, 500, 'text/plain; charset=utf-8', `Storage route failed: ${error.message}`)
      else res.destroy()
    })
  }
  return {
    name: 'manus-storage-routes',
    configResolved(config) { root ??= config.root },
    // Installed directly so the route runs before Vite's static and SPA fallback middleware.
    configureServer(server) { server.middlewares.use(middleware) },
    configurePreviewServer(server) { server.middlewares.use(middleware) },
  }
}

function send(res, status, type, body, headers = {}) {
  res.writeHead(status, { 'Cache-Control': 'no-store', ...headers, ...(type ? { 'Content-Type': type } : {}) })
  res.end(body)
}
